:root {
  --ink: #041f1b;
  --deep: #073b33;
  --deep-2: #0b4a3f;
  --cream: #fff3da;
  --cream-dim: #e9d7b4;
  --gold: #f6c65e;
  --gold-soft: #ffdc95;
  --red: #e2503c;
  --leaf: #2f9b6b;
  --panel: rgba(6, 42, 36, 0.72);
  --panel-line: rgba(246, 198, 94, 0.35);
  --shadow: 0 18px 45px rgba(0, 16, 13, 0.42);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #072b26;
  color: var(--cream);
  font-family: 'Noto Sans Bengali', 'Baloo Da 2', system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body {
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}

#scene {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

.hidden { display: none !important; }

button {
  font-family: inherit;
  color: inherit;
  border: 0;
  cursor: pointer;
  touch-action: manipulation;
}

/* ---------------- loading ---------------- */
.loading {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 16px;
  background:
    radial-gradient(circle at 50% 120%, #145c4c 0%, #072b26 55%, #041d19 100%);
  text-align: center;
  transition: opacity 0.5s ease;
}
.loading p {
  margin: 0;
  font-family: 'Baloo Da 2', sans-serif;
  font-size: clamp(22px, 4vw, 30px);
  font-weight: 700;
  letter-spacing: 0.4px;
}
.loading small { color: var(--cream-dim); opacity: 0.65; }
.rowing { display: flex; align-items: flex-end; gap: 7px; height: 40px; }
.rowing span {
  width: 7px;
  border-radius: 6px;
  background: linear-gradient(180deg, var(--gold-soft), var(--red));
  animation: row 1.05s ease-in-out infinite;
}
.rowing span:nth-child(1) { height: 12px; animation-delay: 0s; }
.rowing span:nth-child(2) { height: 22px; animation-delay: 0.1s; }
.rowing span:nth-child(3) { height: 34px; animation-delay: 0.2s; }
.rowing span:nth-child(4) { height: 22px; animation-delay: 0.3s; }
.rowing span:nth-child(5) { height: 12px; animation-delay: 0.4s; }
@keyframes row {
  0%, 100% { transform: scaleY(0.6); opacity: 0.7; }
  50% { transform: scaleY(1.25); opacity: 1; }
}

/* ---------------- screens ---------------- */
.screen { position: fixed; inset: 0; z-index: 20; }
.screen.menu {
  display: flex;
  align-items: center;
  padding: clamp(18px, 4vw, 64px);
  padding-left: clamp(18px, 6vw, 96px);
  background:
    linear-gradient(90deg, rgba(3, 28, 24, 0.92) 0%, rgba(3, 28, 24, 0.74) 38%, rgba(3, 28, 24, 0.24) 68%, rgba(3, 28, 24, 0.02) 100%);
  overflow: hidden;
}
.menu-fade {
  position: absolute;
  left: 0; right: 0; bottom: 0;
  height: 26vh;
  background: linear-gradient(180deg, transparent, rgba(2, 20, 17, 0.75));
  pointer-events: none;
}
.menu-inner {
  position: relative;
  z-index: 2;
  max-width: 580px;
  animation: rise 0.8s cubic-bezier(0.2, 0.9, 0.25, 1) both;
}
@keyframes rise {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: none; }
}

.brand { display: flex; align-items: center; gap: 12px; margin-bottom: 4px; }
.brand-word {
  font-family: 'Baloo Da 2', sans-serif;
  font-weight: 700;
  font-size: clamp(14px, 2.4vw, 18px);
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--gold);
  opacity: 0.9;
}
.brand-3d {
  font-family: 'Baloo Da 2', sans-serif;
  font-weight: 800;
  font-size: clamp(11px, 1.6vw, 13px);
  padding: 3px 9px;
  border-radius: 6px;
  color: #3b1f06;
  background: linear-gradient(160deg, var(--gold-soft), var(--gold));
  box-shadow: 0 4px 0 rgba(120, 72, 10, 0.5);
  transform: rotate(-4deg);
}

.menu h1 {
  margin: 0;
  font-family: 'Baloo Da 2', sans-serif;
  font-weight: 800;
  font-size: clamp(64px, 13vw, 132px);
  line-height: 0.92;
  letter-spacing: -0.01em;
  background: linear-gradient(180deg, #fff8e8 8%, var(--gold-soft) 46%, #ef9c3d 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 8px 0 rgba(84, 41, 8, 0.35)) drop-shadow(0 18px 28px rgba(0, 0, 0, 0.35));
}
.rule { display: flex; align-items: center; gap: 10px; margin: 14px 0 8px; max-width: 360px; }
.rule i { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, var(--gold), transparent); opacity: 0.65; }
.rule b { color: var(--gold); font-size: 14px; }

.tagline {
  margin: 0 0 14px;
  font-family: 'Baloo Da 2', sans-serif;
  font-size: clamp(19px, 3vw, 25px);
  font-weight: 600;
  color: #ffe1ab;
  letter-spacing: 0.01em;
}
.desc {
  margin: 0 0 26px;
  max-width: 470px;
  font-size: clamp(13.5px, 1.6vw, 15.5px);
  line-height: 1.75;
  color: rgba(255, 243, 218, 0.78);
