.primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 58px;
  padding: 0 30px;
  border-radius: 16px;
  font-family: 'Baloo Da 2', sans-serif;
  font-size: 22px;
  font-weight: 700;
