.primary svg { width: 24px; height: 24px; }
.primary:hover { filter: brightness(1.05); transform: translateY(-1px); }
.primary:active { transform: translateY(4px); box-shadow: 0 3px 0 #a86414, 0 8px 18px rgba(0, 0, 0, 0.3); }
.primary:focus-visible, .ghost:focus-visible, .icon-btn:focus-visible, .touch-btn:focus-visible, .touch-boost:focus-visible {
  outline: 2px solid var(--gold-soft);
  outline-offset: 3px;
}

.menu-meta { margin-top: 26px; display: grid; gap: 13px; }
.best {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  align-self: start;
  padding: 8px 16px;
  border: 1px solid rgba(246, 198, 94, 0.3);
  border-radius: 12px;
  background: rgba(5, 38, 32, 0.55);
  backdrop-filter: blur(6px);
}
.best span { font-size: 12.5px; letter-spacing: 0.08em; color: rgba(255, 243, 218, 0.6); }
.best strong { font-family: 'Baloo Da 2', sans-serif; font-size: 19px; color: var(--gold-soft); letter-spacing: 0.04em; }

.chips { display: flex; flex-wrap: wrap; gap: 8px; max-width: 500px; }
.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: 9px;
  font-size: 12.5px;
  color: rgba(255, 243, 218, 0.72);
  background: rgba(5, 38, 32, 0.45);
  border: 1px solid rgba(255, 243, 218, 0.1);
}
