  display: inline-grid;
  place-items: center;
  min-width: 20px;
  height: 20px;
  padding: 0 4px;
  border-radius: 5px;
  font-family: inherit;
  font-size: 11px;
  color: var(--gold-soft);
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(255, 243, 218, 0.16);
