401:   border-radius: 14px;
402:   background: var(--panel);
403:   border: 1px solid var(--panel-line);
404:   backdrop-filter: blur(8px);
405: }
406: .speed span { font-size: 11px; letter-spacing: 0.1em; color: rgba(255, 243, 218, 0.55); }
407: .speed strong { font-family: 'Baloo Da 2', sans-serif; font-size: 30px; line-height: 1; color: var(--cream); font-variant-numeric: tabular-nums; }
408: .speed small { font-size: 10px; color: rgba(255, 243, 218, 0.55); }
409: 
410: .toast {
411:   position: absolute;
412:   top: 19%;
413:   left: 50%;
414:   transform: translate(-50%, -8px);
415:   padding: 9px 20px;
416:   border-radius: 999px;
417:   font-family: 'Baloo Da 2', sans-serif;
418:   font-size: 17px;
419:   font-weight: 600;
420:   color: #2a1604;
421:   background: linear-gradient(180deg, #ffe3a0, var(--gold));
422:   box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
423:   opacity: 0;
424:   transition: opacity 0.2s ease, transform 0.2s ease;
425:   white-space: nowrap;
426: }
427: .toast.show { opacity: 1; transform: translate(-50%, 0); }
428: 
429: .countdown {
430:   position: absolute;
431:   inset: 0;
432:   display: grid;
433:   place-items: center;
434:   font-family: 'Baloo Da 2', sans-serif;
435:   font-weight: 800;
436:   font-size: clamp(90px, 22vw, 190px);
437:   color: var(--cream);
438:   text-shadow: 0 10px 0 rgba(80, 36, 6, 0.45), 0 24px 60px rgba(0, 0, 0, 0.5);
439:   pointer-events: none;
440:   opacity: 0;
441: }
442: .countdown.pop { animation: countPop 0.9s cubic-bezier(0.16, 1, 0.3, 1) both; }
443: .countdown.go { color: var(--gold-soft); }
444: @keyframes countPop {
445:   0% { opacity: 0; transform: scale(1.6); }
446:   18% { opacity: 1; transform: scale(0.95); }
447:   32% { transform: scale(1); }
448:   75% { opacity: 1; }
449:   100% { opacity: 0; transform: scale(0.86); }
450: }
