459:   gap: 10px;
460: }
461: .touch-btn {
462:   width: 66px;
463:   height: 66px;
464:   display: grid;
465:   place-items: center;
466:   border-radius: 50%;
467:   color: var(--cream);
468:   background: rgba(4, 42, 35, 0.55);
469:   border: 1.5px solid rgba(255, 243, 218, 0.26);
470:   backdrop-filter: blur(5px);
471:   box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.14);
472:   transition: transform 0.06s ease, background 0.1s ease;
473: }
474: .touch-btn svg { width: 30px; height: 30px; }
475: .touch-btn.active, .touch-btn:active { transform: scale(0.92); background: rgba(246, 198, 94, 0.35); }
476: .touch-boost {
477:   position: absolute;
478:   right: max(18px, env(safe-area-inset-right));
479:   bottom: max(22px, env(safe-area-inset-bottom));
480:   width: 86px;
481:   height: 86px;
482:   border-radius: 50%;
483:   font-family: 'Baloo Da 2', sans-serif;
484:   font-size: 17px;
485:   font-weight: 700;
486:   color: #2a1604;
487:   background: radial-gradient(circle at 35% 30%, #ffe8ae, var(--gold) 60%, #e39a2e);
488:   border: 1.5px solid rgba(255, 255, 255, 0.5);
489:   box-shadow: 0 8px 0 #9d5f11, 0 16px 28px rgba(0, 0, 0, 0.38);
490:   transition: transform 0.07s ease, box-shadow 0.07s ease;
491: }
492: .touch-boost.active, .touch-boost:active { transform: translateY(5px); box-shadow: 0 3px 0 #9d5f11, 0 8px 18px rgba(0, 0, 0, 0.35); }
493: .touch-boost-ring {
494:   position: absolute;
495:   inset: 6px;
496:   border-radius: 50%;
497:   border: 1.5px dashed rgba(86, 44, 4, 0.35);
498:   pointer-events: none;
