513:   box-shadow: 0 30px 90px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.1);
514:   animation: rise 0.35s cubic-bezier(0.2, 0.9, 0.25, 1) both;
515: }
516: #pause, #results {
517:   display: grid;
518:   place-items: center;
519:   background: rgba(3, 22, 19, 0.58);
520:   backdrop-filter: blur(7px);
521:   padding: 18px;
522: }
523: #pause .card, #results .card {
524:   position: relative;
525:   left: auto;
526:   top: auto;
527:   transform: none;
528:   width: min(92vw, 480px);
529: }
530: .eyebrow {
531:   margin: 0 0 4px;
532:   font-size: 11.5px;
533:   letter-spacing: 0.22em;
534:   text-transform: uppercase;
535:   color: var(--gold);
536:   opacity: 0.8;
537: }
538: .card h2 {
539:   margin: 0 0 20px;
540:   font-family: 'Baloo Da 2', sans-serif;
541:   font-size: clamp(26px, 4.5vw, 36px);
542:   font-weight: 700;
543:   line-height: 1.2;
544:   color: var(--cream);
545: }
546: .card .primary { width: 100%; margin-top: 4px; }
547: .row { display: flex; gap: 8px; margin-top: 10px; }
