602: 
603: /* ---------------- responsive ---------------- */
604: @media (hover: none), (pointer: coarse) {
605:   .touch { display: block; }
606:   .chips { display: none; }
607:   .touch-hint { display: block; }
608:   .speed { bottom: max(122px, calc(env(safe-area-inset-bottom) + 110px)); right: max(16px, env(safe-area-inset-right)); padding: 6px 12px 7px; }
609:   .speed strong { font-size: 24px; }
610:   .boost {
611:     left: max(16px, env(safe-area-inset-left));
612:     bottom: max(108px, calc(env(safe-area-inset-bottom) + 96px));
613:     width: 160px;
614:   }
615:   #minimap { width: 108px; height: 108px; top: calc(max(12px, env(safe-area-inset-top)) + 52px); }
616:   .stat { min-width: 62px; padding: 5px 9px 6px; }
617:   .stat strong { font-size: 18px; }
618:   .hud-buttons { gap: 6px; }
619:   .icon-btn { width: 38px; height: 38px; }
620:   .timer-wrap { padding: 2px 14px 4px; }
621: }
622: 
623: @media (max-width: 720px) {
624:   .screen.menu {
625:     align-items: flex-start;
626:     padding-top: max(30px, env(safe-area-inset-top));
627:     background: linear-gradient(180deg, rgba(3, 28, 24, 0.9) 0%, rgba(3, 28, 24, 0.6) 45%, rgba(3, 28, 24, 0.2) 100%);
628:     overflow-y: auto;
629:   }
630:   .menu-inner { max-width: 100%; }
631:   .menu h1 { font-size: clamp(58px, 18vw, 96px); }
632:   .desc { margin-bottom: 20px; max-width: 94%; }
633:   .primary { width: 100%; }
634:   .best { align-self: start; }
635:   .footnote { letter-spacing: 0.1em; font-size: 10.5px; margin-top: 18px; }
636:   .menu-fade { display: none; }
637:   .loader { transform: scale(0.9); }
638: }
639: 
640: @media (max-height: 560px) and (orientation: landscape) {
641:   .menu-inner { max-width: 60%; }
642:   .menu h1 { font-size: clamp(44px, 10vw, 76px); }
643:   .desc, .chips, .touch-hint { display: none; }
644:   .menu-meta { margin-top: 14px; }
645:   .primary { width: auto; min-height: 48px; font-size: 18px; padding: 0 22px; }
646:   .brand-word { display: none; }
